# Migrating Flat Pulumi Program to ComponentResource with Aliases

## Problem

When you wrap resources in a `ComponentResource`, Pulumi changes their URN path. Pulumi then sees the new URN as a *different* resource and plans **destroy + create** (replacement). `aliases` tells Pulumi that the new URN is the same logical resource as the old one, preserving state continuity.

---

## Before: Flat Program

```typescript
// index.ts (flat)
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as kubernetes from "@pulumi/kubernetes";

const config = new pulumi.Config();

// --- S3 Bucket ---
const bucket = new aws.s3.Bucket("app-assets", {
    bucket: `app-assets-${config.getStack()}`,
    versioning: { enabled: true },
    tags: { "env": config.getStack() },
});

const bucketAcl = new aws.s3.BucketAcl("app-assets-acl", {
    bucket: bucket.id,
    acl: "private",
});

const bucketEncryption = new aws.s3.BucketServerSideEncryptionConfiguration(
    "app-assets-encryption",
    {
        bucket: bucket.id,
        rules: [{
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        }],
    }
);

const bucketPublicAccess = new aws.s3.BucketPublicAccessBlock(
    "app-assets-public-access",
    {
        bucket: bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
    }
);

// --- RDS ---
const dbSubnetGroup = new aws.rds.SubnetGroup("app-db-subnets", {
    subnetIds: config.requireObject<string[]>("dbSubnetIds"),
    tags: { "env": config.getStack() },
});

const dbSecurityGroup = new aws.ec2.SecurityGroup("app-db-sg", {
    description: "Allow RDS access from VPC",
    vpcId: config.require("vpcId"),
    ingress: [
        { protocol: "tcp", fromPort: 5432, toPort: 5432, cidrBlocks: ["10.0.0.0/8"] },
    ],
    egress: [{ protocol: "-1", cidrBlocks: ["0.0.0.0/0"] }],
    tags: { "env": config.getStack() },
});

const db = new aws.rds.Instance("app-db", {
    identifier: `app-db-${config.getStack()}`,
    engine: "postgres",
    engineVersion: "15.4",
    instanceClass: config.require("dbInstanceClass"), // db.t3.micro | db.t3.medium
    allocatedStorage: 20,
    dbName: "app",
    username: "appuser",
    password: config.requireSecret("dbPassword"),
    dbSubnetGroupName: dbSubnetGroup.name,
    vpcSecurityGroupIds: [dbSecurityGroup.id],
    multiAz: config.getBoolean("multiAz") ?? false,
    deletionProtection: true,
    backupRetentionPeriod: 7,
    publiclyAccessible: false,
    storageEncrypted: config.getBoolean("storageEncrypted") ?? false,
    tags: { "env": config.getStack() },
});

// --- IAM Role ---
const role = new aws.iam.Role("app-service-role", {
    assumeRolePolicy: aws.iam.assumeRolePolicyDocument({
        statements: [{
            effect: "Allow",
            principals: [{ type: "Service", identifiers: ["ecs-tasks.amazonaws.com"] }],
            actions: ["sts:AssumeRole"],
        }],
    }),
    tags: { "env": config.getStack() },
});

const rolePolicy = new aws.iam.RolePolicy("app-service-role-policy", {
    role: role.id,
    policy: pulumi.jsonStringify({
        Version: "2012-10-17",
        Statement: [
            {
                Effect: "Allow",
                Action: ["s3:GetObject", "s3:ListBucket"],
                Resource: [bucket.arn, bucket.arn.apply(a => `${a}/*`)],
            },
        ],
    }),
});

// --- EKS Cluster ---
const vpc = aws.ec2.getVpcOutput({ vpcId: config.require("vpcId") });
const cluster = new aws.eks.Cluster("app-eks", {
    roleArn: new aws.iam.Role("app-eks-role", {
        assumeRolePolicy: aws.iam.assumeRolePolicyDocument({
            statements: [{
                effect: "Allow",
                principals: [{ type: "Service", identifiers: ["eks.amazonaws.com"] }],
                actions: ["sts:AssumeRole"],
            }],
        }),
    }).then(r => r.arn),
    vpcConfig: {
        subnetIds: config.requireObject<string[]>("eksSubnetIds"),
    },
    tags: { "env": config.getStack() },
});

const nodeGroup = new aws.eks.NodeGroup("app-eks-ng", {
    clusterName: cluster.name,
    instanceTypes: [config.require("nodeInstanceType")], // t3.medium | t3.large
    scalingConfig: {
        desiredSize: config.getNumber("nodeCount")!, // 2 | 4
        minSize: 1,
        maxSize: 6,
    },
    subnetIds: config.requireObject<string[]>("eksSubnetIds"),
    tags: { "env": config.getStack() },
});

// --- ALB (dev) / CloudFront (prod) ---
const alb = new aws.elbv2.LoadBalancer("app-alb", {
    name: `app-alb-${config.getStack()}`,
    internal: config.getBoolean("internalAlb") ?? true,
    loadBalancerType: "application",
    securityGroups: [dbSecurityGroup.id], // simplified; real app would use a dedicated SG
    subnets: config.requireObject<string[]>("albSubnetIds"),
    tags: { "env": config.getStack() },
});

const albListener = new aws.elbv2.Listener("app-alb-443", {
    loadBalancerArn: alb.arn,
    port: 443,
    protocol: "HTTPS",
    sslPolicy: "ELBSecurityPolicy-2016-08",
    certificates: [{ certificateArn: config.require("certArn") }],
    defaultActions: [{
        type: "forward",
        targetGroupArns: [
            new aws.elbv2.TargetGroup("app-alb-tg", {
                name: `app-alb-tg-${config.getStack()}`,
                port: 8080,
                protocol: "HTTP",
                targetType: "ip",
                vpcId: config.require("vpcId"),
                healthCheck: {
                    healthyStatusCodes: "200-299",
                    matcher: "200",
                },
            }).then(tg => tg.arn),
        ],
    }],
});

// --- Secrets via Pulumi Config ---
const dbConnectionString = new pulumi.secret(
    pulumi.interpolate`postgresql://appuser:${config.requireSecret("dbPassword")}@${db.address}:5432/app`
);

// --- Outputs ---
export const bucketName = bucket.id;
export const dbEndpoint = db.address;
export const clusterEndpoint = cluster.endpoint;
export const albDns = alb.dnsName;
export const dbConnectionStringSecret = dbConnectionString;
```

---

## After: ComponentResource Migration with Aliases

### The migrated `index.ts`

```typescript
// index.ts (migrated)
import * as pulumi from "@pulumi/pulumi";
import { AppInfrastructure } from "./components/app-infrastructure";

const config = new pulumi.Config();

const stack = config.getStack()!;

const app = new AppInfrastructure("app", {
    stack,
    vpcId: config.require("vpcId"),
    dbSubnetIds: config.requireObject<string[]>("dbSubnetIds"),
    eksSubnetIds: config.requireObject<string[]>("eksSubnetIds"),
    albSubnetIds: config.requireObject<string[]>("albSubnetIds"),
    dbInstanceClass: config.require("dbInstanceClass"),
    multiAz: config.getBoolean("multiAz") ?? false,
    storageEncrypted: config.getBoolean("storageEncrypted") ?? false,
    nodeInstanceType: config.require("nodeInstanceType"),
    nodeCount: config.getNumber("nodeCount")!,
    internalAlb: config.getBoolean("internalAlb") ?? true,
    certArn: config.require("certArn"),
    // Secrets are passed through; the component re-wraps them
    dbPassword: config.requireSecret("dbPassword"),
});

export const bucketName = app.bucketName;
export const dbEndpoint = app.dbEndpoint;
export const clusterEndpoint = app.clusterEndpoint;
export const albDns = app.albDns;
export const dbConnectionStringSecret = app.dbConnectionString;
```

### The Component: `components/app-infrastructure.ts`

```typescript
// components/app-infrastructure.ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppInfrastructureArgs {
    stack: string;
    vpcId: string;
    dbSubnetIds: string[];
    eksSubnetIds: string[];
    albSubnetIds: string[];
    dbInstanceClass: string;
    multiAz: boolean;
    storageEncrypted: boolean;
    nodeInstanceType: string;
    nodeCount: number;
    internalAlb: boolean;
    certArn: string;
    dbPassword: pulumi.Output<string>;
}

export class AppInfrastructure extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly clusterEndpoint: pulumi.Output<string>;
    public readonly albDns: pulumi.Output<string>;
    public readonly dbConnectionString: pulumi.Output<string>;

    constructor(name: string, args: AppInfrastructureArgs, opts?: pulumi.ComponentResourceOptions) {
        super("appinfra:components:AppInfrastructure", name, {}, opts);

        const { stack } = args;

        // ─── S3 Bucket ───────────────────────────────────────────────

        const bucket = new aws.s3.Bucket("app-assets", {
            bucket: `app-assets-${stack}`,
            versioning: { enabled: true },
            tags: { env: stack },
            // CRITICAL: alias back to the flat-program URN
            // Old URN: urn:pulumi:dev::webapp::aws:s3/bucket:Bucket::app-assets
            // New URN: urn:pulumi:dev::webapp::appinfra:components:AppInfrastructure::app::aws:s3/bucket:Bucket::app-assets
            opts: {
                parent: this,
                // The alias must be the OLD URN (the fully-qualified path)
                aliases: [`urn:pulumi:${stack}::webapp::aws:s3/bucket:Bucket::app-assets`],
            },
        });

        const bucketAcl = new aws.s3.BucketAcl("app-assets-acl", {
            bucket: bucket.id,
            acl: "private",
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:s3/bucket:BucketAcl::app-assets-acl`],
            },
        });

        const bucketEncryption = new aws.s3.BucketServerSideEncryptionConfiguration(
            "app-assets-encryption",
            {
                bucket: bucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
                }],
                opts: {
                    parent: this,
                    aliases: [
                        `urn:pulumi:${stack}::webapp::aws:s3/bucket:BucketServerSideEncryptionConfiguration::app-assets-encryption`,
                    ],
                },
            }
        );

        const bucketPublicAccess = new aws.s3.BucketPublicAccessBlock(
            "app-assets-public-access",
            {
                bucket: bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
                opts: {
                    parent: this,
                    aliases: [
                        `urn:pulumi:${stack}::webapp::aws:s3/bucket:BucketPublicAccessBlock::app-assets-public-access`,
                    ],
                },
            }
        );

        // ─── RDS ─────────────────────────────────────────────────────

        const dbSubnetGroup = new aws.rds.SubnetGroup("app-db-subnets", {
            subnetIds: args.dbSubnetIds,
            tags: { env: stack },
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:rds/subnetGroup:SubnetGroup::app-db-subnets`],
            },
        });

        const dbSecurityGroup = new aws.ec2.SecurityGroup("app-db-sg", {
            description: "Allow RDS access from VPC",
            vpcId: args.vpcId,
            ingress: [{ protocol: "tcp", fromPort: 5432, toPort: 5432, cidrBlocks: ["10.0.0.0/8"] }],
            egress: [{ protocol: "-1", cidrBlocks: ["0.0.0.0/0"] }],
            tags: { env: stack },
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:ec2/securityGroup:SecurityGroup::app-db-sg`],
            },
        });

        const db = new aws.rds.Instance("app-db", {
            identifier: `app-db-${stack}`,
            engine: "postgres",
            engineVersion: "15.4",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: 20,
            dbName: "app",
            username: "appuser",
            password: args.dbPassword,
            dbSubnetGroupName: dbSubnetGroup.name,
            vpcSecurityGroupIds: [dbSecurityGroup.id],
            multiAz: args.multiAz,
            deletionProtection: true,
            backupRetentionPeriod: 7,
            publiclyAccessible: false,
            storageEncrypted: args.storageEncrypted,
            tags: { env: stack },
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:rds/instance:Instance::app-db`],
            },
        });

        // ─── IAM Role ────────────────────────────────────────────────

        const role = new aws.iam.Role("app-service-role", {
            assumeRolePolicy: aws.iam.assumeRolePolicyDocument({
                statements: [{
                    effect: "Allow",
                    principals: [{ type: "Service", identifiers: ["ecs-tasks.amazonaws.com"] }],
                    actions: ["sts:AssumeRole"],
                }],
            }),
            tags: { env: stack },
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:iam/role:Role::app-service-role`],
            },
        });

        const rolePolicy = new aws.iam.RolePolicy("app-service-role-policy", {
            role: role.id,
            policy: pulumi.jsonStringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Action: ["s3:GetObject", "s3:ListBucket"],
                    Resource: [bucket.arn, bucket.arn.apply(a => `${a}/*`)],
                }],
            }),
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:iam/rolePolicy:RolePolicy::app-service-role-policy`],
            },
        });

        // ─── EKS Cluster ─────────────────────────────────────────────

        const eksRole = new aws.iam.Role("app-eks-role", {
            assumeRolePolicy: aws.iam.assumeRolePolicyDocument({
                statements: [{
                    effect: "Allow",
                    principals: [{ type: "Service", identifiers: ["eks.amazonaws.com"] }],
                    actions: ["sts:AssumeRole"],
                }],
            }),
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:iam/role:Role::app-eks-role`],
            },
        });

        const cluster = new aws.eks.Cluster("app-eks", {
            roleArn: eksRole.arn,
            vpcConfig: { subnetIds: args.eksSubnetIds },
            tags: { env: stack },
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:eks/cluster:Cluster::app-eks`],
            },
        });

        const nodeGroup = new aws.eks.NodeGroup("app-eks-ng", {
            clusterName: cluster.name,
            instanceTypes: [args.nodeInstanceType],
            scalingConfig: { desiredSize: args.nodeCount, minSize: 1, maxSize: 6 },
            subnetIds: args.eksSubnetIds,
            tags: { env: stack },
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:eks/nodeGroup:NodeGroup::app-eks-ng`],
            },
        });

        // ─── ALB ─────────────────────────────────────────────────────

        const targetGroup = new aws.elbv2.TargetGroup("app-alb-tg", {
            name: `app-alb-tg-${stack}`,
            port: 8080,
            protocol: "HTTP",
            targetType: "ip",
            vpcId: args.vpcId,
            healthCheck: { healthyStatusCodes: "200-299", matcher: "200" },
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:elbv2/targetGroup:TargetGroup::app-alb-tg`],
            },
        });

        const alb = new aws.elbv2.LoadBalancer("app-alb", {
            name: `app-alb-${stack}`,
            internal: args.internalAlb,
            loadBalancerType: "application",
            securityGroups: [dbSecurityGroup.id],
            subnets: args.albSubnetIds,
            tags: { env: stack },
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:elbv2/loadBalancer:LoadBalancer::app-alb`],
            },
        });

        const albListener = new aws.elbv2.Listener("app-alb-443", {
            loadBalancerArn: alb.arn,
            port: 443,
            protocol: "HTTPS",
            sslPolicy: "ELBSecurityPolicy-2016-08",
            certificates: [{ certificateArn: args.certArn }],
            defaultActions: [{ type: "forward", targetGroupArns: [targetGroup.arn] }],
            opts: {
                parent: this,
                aliases: [`urn:pulumi:${stack}::webapp::aws:elbv2/listener:Listener::app-alb-443`],
            },
        });

        // ─── Secret ──────────────────────────────────────────────────

        this.dbConnectionString = new pulumi.secret(
            pulumi.interpolate`postgresql://appuser:${args.dbPassword}@${db.address}:5432/app`
        );

        // ─── Register outputs ────────────────────────────────────────

        this.registerOutputs({
            bucketName: bucket.id,
            dbEndpoint: db.address,
            clusterEndpoint: cluster.endpoint,
            albDns: alb.dnsName,
            dbConnectionString: this.dbConnectionString,
        });
    }
}
```

